-- Export the reconciliation results for Power BI.
-- Run from the project root AFTER sql/03_reconciliation.sql:
--   psql -d p2p -f sql/04_export_powerbi.sql
\! mkdir -p powerbi/data
\copy (SELECT supplier_id, supplier_name, country, currency, payment_terms_days FROM suppliers ORDER BY supplier_id) TO 'powerbi/data/dim_suppliers.csv' WITH (FORMAT csv, HEADER true)
\copy (SELECT t.po_id, t.invoice_id, t.supplier_id, t.currency, t.po_date, DATE_TRUNC('month', t.po_date)::date AS po_month, t.qty_ordered, t.qty_received, t.qty_invoiced, t.po_price, t.invoice_price, t.invoice_date, t.receipt_date, t.invoice_amount, ROUND(t.invoice_amount * CASE WHEN t.currency = 'EUR' THEN fx.eur_pln ELSE 1 END, 2) AS invoice_amount_pln, t.match_status, CASE WHEN t.match_status IN ('MATCHED', 'MATCHED_TIMING') THEN 1 ELSE 0 END AS is_matched, ROUND(COALESCE(t.overbilled_amount, 0) * CASE WHEN t.currency = 'EUR' THEN fx.eur_pln ELSE 1 END, 2) AS overbilled_pln FROM v_three_way t LEFT JOIN fx_rates fx ON fx.rate_date = t.invoice_date ORDER BY t.po_id) TO 'powerbi/data/fact_three_way.csv' WITH (FORMAT csv, HEADER true)
\copy (SELECT payment_id, payment_date, DATE_TRUNC('month', payment_date)::date AS payment_month, supplier_id, invoice_id, invoice_number, currency, amount_pln, expected_pln, diff_pln, payment_status FROM v_payment_status ORDER BY payment_id) TO 'powerbi/data/fact_payments.csv' WITH (FORMAT csv, HEADER true)
\copy (SELECT d.invoice_id, d.invoice_number, d.supplier_id, d.invoice_date, d.amount, d.currency, ROUND(d.amount * CASE WHEN d.currency = 'EUR' THEN fx.eur_pln ELSE 1 END, 2) AS amount_pln FROM v_duplicate_invoices d LEFT JOIN fx_rates fx ON fx.rate_date = d.invoice_date ORDER BY d.invoice_id) TO 'powerbi/data/fact_duplicates.csv' WITH (FORMAT csv, HEADER true)
\copy (SELECT source, ref_id, supplier_id, discrepancy_type, amount, currency FROM v_discrepancy_report ORDER BY discrepancy_type, ref_id) TO 'powerbi/data/fact_discrepancies.csv' WITH (FORMAT csv, HEADER true)
\copy (SELECT p.* FROM bank_payments p WHERE NOT EXISTS (SELECT 1 FROM supplier_invoices i WHERE i.invoice_number = p.transfer_title) ORDER BY p.payment_date) TO 'powerbi/data/fact_unmatched_payments.csv' WITH (FORMAT csv, HEADER true)
\echo 'Exported 6 files to powerbi/data/'
